    text = payload['text']
    words = re.findall(r'[A-Za-z]+', text)
    counts = {}
    for w in words:
        w = w.lower()
        counts[w] = counts.get(w, 0) + 1
    frequencies = [{'word': w, 'count': c} for w, c in counts.items()]
    frequencies.sort(key=lambda item: (-item['count'], item['word']))
    return {'frequencies': frequencies}
